const CATEGORIES = {
  "acces_connexion": "connexion, mot de passe, double authentification, création ou désactivation d'utilisateurs, droits d'accès, message « Accès refusé »",
  "facturation_comptabilite": "factures clients ou fournisseurs, avoirs, paiements, TVA et taxes, rapprochement bancaire, comptabilité",
  "ventes_crm": "devis, commandes clients, listes de prix, remises, CRM, pistes et opportunités",
  "achats_stock": "achats fournisseurs, réceptions, livraisons, inventaire, quantités en stock, réapprovisionnement",
  "import_export": "import ou export de fichiers CSV/Excel, mise à jour de données en masse, migration de données",
  "technique_bug": "erreur serveur, traceback, bug, lenteur, module, mise à jour de module, mode développeur",
  "hebergement_odoosh": "Odoo.sh : branches, staging, sauvegardes, restauration, build en échec, nom de domaine",
  "autre": "tout le reste : demande commerciale, développement spécifique, hors sujet"
};
const PRIORITIES = {
  critique: "production arrêtée, perte de données, faille de sécurité, toute l'entreprise bloquée",
  haute: "fonction métier importante bloquée (facturer, livrer, se connecter pour travailler) sans contournement",
  normale: "gêne avec contournement possible, question fonctionnelle sur l'utilisation",
  basse: "demande d'information, suggestion, question générale non urgente",
};
const t = $json;
const system = [
  "Tu es l'agent de tri du support d'un intégrateur Odoo (ERP). Tu lis une demande client et tu la classes.",
  "Catégories possibles :", ...Object.entries(CATEGORIES).map(([k, v]) => `- ${k} : ${v}`),
  "Priorités :", ...Object.entries(PRIORITIES).map(([k, v]) => `- ${k} : ${v}`),
  "Par défaut la priorité est normale. N'utilise critique que si TOUTE l'entreprise ou la production est bloquée, et haute seulement si une personne ne peut plus travailler.",
  "Une simple question (« comment faire… ? ») est normale ou basse, jamais haute ni critique.",
  "wants_human = true UNIQUEMENT si le message contient une demande explicite de parler à un humain, un conseiller, ou d'être rappelé. Sinon false.",
  "confidence = ta certitude entre 0 et 1 sur la catégorie ET la priorité (0.9 = évident, 0.6 = hésitation, < 0.4 = demande floue ou hors sujet).",
  "Exemples :",
  "« J'ai oublié mon mot de passe » → acces_connexion, normale, wants_human false",
  "« Comment créer un avoir ? » → facturation_comptabilite, basse, wants_human false",
  "« Plus personne ne peut se connecter, la production est arrêtée » → technique_bug, critique, wants_human false",
  "« Je veux parler à un conseiller pour ma facture » → facturation_comptabilite, normale, wants_human true",
  "summary = résumé du problème en une phrase, en français. reason = justification courte de la priorité.",
  "Réponds uniquement avec l'objet JSON demandé.",
].join('\n');
const schema = {
  type: 'object',
  // Ordre volontaire : le modèle résume et justifie AVANT de choisir (meilleur tri pour un petit modèle)
  properties: {
    summary: { type: 'string' },
    category: { type: 'string', enum: Object.keys(CATEGORIES) },
    reason: { type: 'string' },
    priority: { type: 'string', enum: Object.keys(PRIORITIES) },
    wants_human: { type: 'boolean' },
    confidence: { type: 'number', minimum: 0, maximum: 1 },
  },
  required: ['summary', 'category', 'reason', 'priority', 'wants_human', 'confidence'],
};
const user = `Sujet : ${t.subject || '(aucun)'}\nCanal : ${t.channel}\nMessage :\n${t.body}`;
return { json: { ticket_id: Number(t.id), body: t.body, subject: t.subject, request: {
  stream: false, format: schema, options: { temperature: 0, num_ctx: 4096, num_predict: 256 },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
} } };

const CATS = ["acces_connexion", "facturation_comptabilite", "ventes_crm", "achats_stock", "import_export", "technique_bug", "hebergement_odoosh", "autre"];
const PRIOS = ['basse', 'normale', 'haute', 'critique'];
const src = $('Prompt').item.json;
let r = {}, error = null;
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error));
  r = JSON.parse($json.message?.content || '');
} catch (e) { error = 'classification : ' + e.message; }

const text = `${src.subject || ''}\n${src.body || ''}`;
// Demande explicite d'un humain : détectée par mots-clés ; l'avis du LLM ne compte que si le texte parle d'un humain
const askHuman = /\b(parler|discuter|échanger|voir)\b.{0,40}\b(humain|conseiller|personne|quelqu'un|technicien|responsable)\b|\b(rappel(ez|er)[- ]?moi|me rappeler|appelez[- ]?moi)\b|\bun conseiller\b/i.test(text);
const mentionsHuman = /humain|conseill|quelqu'un|technicien|agent|t[ée]l[ée]phone|appel/i.test(text);
const category = CATS.includes(r.category) ? r.category : 'autre';
const priority = PRIOS.includes(r.priority) ? r.priority : 'normale';
let confidence = Number(r.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.min(1, Math.max(0, confidence));
if (error) confidence = 0;
return { json: {
  ticket_id: src.ticket_id, category, priority, confidence: Math.round(confidence * 1000) / 1000,
  wants_human: askHuman || (r.wants_human === true && mentionsHuman),
  summary: (r.summary || '').slice(0, 500) || null, reason: (r.reason || '').slice(0, 500) || null,
  model: $json.model || null, error,
} };
